-- ELITES SACCO isolated database schema v1
-- RLS enforced for all tables; no anonymous access.
begin;
create schema if not exists sacco_private;
revoke all on schema sacco_private from public;
grant usage on schema sacco_private to authenticated;
create table public.sacco_members (id uuid primary key default gen_random_uuid(),legacy_name text not null unique,display_name text not null,auth_user_id uuid unique references auth.users(id) on delete set null,member_role text not null default 'member' check (member_role in ('admin','member')),photo_data text,source_record jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.sacco_members enable row level security;
revoke all on public.sacco_members from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_members to service_role;
create table public.sacco_settings (singleton_id boolean primary key default true check (singleton_id=true),value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
alter table public.sacco_settings enable row level security;
revoke all on public.sacco_settings from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_settings to service_role;
create table public.sacco_contributions (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),contribution_month date not null,paid_on date,amount numeric(16,2) not null,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.sacco_contributions enable row level security;
revoke all on public.sacco_contributions from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_contributions to service_role;
create table public.sacco_loans (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),loan_number integer not null check (loan_number>0),issued_on date not null,principal numeric(16,2) not null,loan_type text not null default 'REGULAR',manual_status text,frozen_total numeric(16,2),legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(member_id,loan_number),unique(id,member_id));
alter table public.sacco_loans enable row level security;
revoke all on public.sacco_loans from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_loans to service_role;
create table public.sacco_repayments (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),loan_id uuid not null,paid_on date not null,amount numeric(16,2) not null,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb,foreign key(loan_id,member_id) references public.sacco_loans(id,member_id));
alter table public.sacco_repayments enable row level security;
revoke all on public.sacco_repayments from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_repayments to service_role;
create table public.sacco_financial_entries (id uuid primary key default gen_random_uuid(),entry_kind text not null check(entry_kind in('cash_in','expense','investment')),entry_on date,amount numeric(16,2) not null,narrative text,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb);
alter table public.sacco_financial_entries enable row level security;
revoke all on public.sacco_financial_entries from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_financial_entries to service_role;
create table public.sacco_membership_fees (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),paid_on date,amount numeric(16,2) not null,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb);
alter table public.sacco_membership_fees enable row level security;
revoke all on public.sacco_membership_fees from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_membership_fees to service_role;
create table public.sacco_waivers (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),contribution_month date not null,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb);
alter table public.sacco_waivers enable row level security;
revoke all on public.sacco_waivers from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_waivers to service_role;
create table public.sacco_minutes (id uuid primary key default gen_random_uuid(),title text,meeting_on date,body text,legacy_key text not null unique,source_record jsonb not null default '{}'::jsonb);
alter table public.sacco_minutes enable row level security;
revoke all on public.sacco_minutes from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_minutes to service_role;
create table public.sacco_requests (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.sacco_members(id),request_kind text not null,amount numeric(16,2) not null,note text,submitted_on date,payment_on date,contribution_month date,legacy_loan_number integer,screenshot_data text,status text not null default 'PENDING',legacy_key text unique,source_record jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.sacco_requests enable row level security;
revoke all on public.sacco_requests from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_requests to service_role;
create table public.sacco_audit_entries (id uuid primary key default gen_random_uuid(),actor_user_id uuid,event_kind text not null,entity_table text,entity_id text,before_record jsonb,after_record jsonb,source_record jsonb,legacy_key text unique,created_at timestamptz not null default now());
alter table public.sacco_audit_entries enable row level security;
revoke all on public.sacco_audit_entries from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_audit_entries to service_role;
create table public.sacco_import_runs (id uuid primary key default gen_random_uuid(),backup_sha256 text not null unique,totals jsonb not null,imported_at timestamptz not null default now());
alter table public.sacco_import_runs enable row level security;
revoke all on public.sacco_import_runs from public,anon,authenticated;
grant select,insert,update,delete on public.sacco_import_runs to service_role;
create index sacco_members_auth_idx on public.sacco_members(auth_user_id);
create index sacco_contributions_member_idx on public.sacco_contributions(member_id,contribution_month);
create index sacco_loans_member_idx on public.sacco_loans(member_id);
create index sacco_repayments_member_idx on public.sacco_repayments(member_id,loan_id);
create index sacco_requests_member_idx on public.sacco_requests(member_id,status);
create function sacco_private.is_sacco_admin() returns boolean language sql stable security definer set search_path='' as $$select (select auth.uid()) is not null and exists(select 1 from public.sacco_members m where m.auth_user_id=(select auth.uid()) and m.member_role='admin')$$;
revoke all on function sacco_private.is_sacco_admin() from public,anon;
grant execute on function sacco_private.is_sacco_admin() to authenticated;
grant select on public.sacco_members,public.sacco_settings,public.sacco_contributions,public.sacco_loans,public.sacco_repayments,public.sacco_financial_entries,public.sacco_membership_fees,public.sacco_waivers,public.sacco_minutes,public.sacco_requests,public.sacco_audit_entries,public.sacco_import_runs to authenticated;
grant insert,update,delete on public.sacco_settings,public.sacco_contributions,public.sacco_loans,public.sacco_repayments,public.sacco_financial_entries,public.sacco_membership_fees,public.sacco_waivers,public.sacco_minutes,public.sacco_requests to authenticated;
create policy sacco_members_read on public.sacco_members for select to authenticated using(auth_user_id=(select auth.uid()) or (select sacco_private.is_sacco_admin()));
create policy sacco_settings_read on public.sacco_settings for select to authenticated using(exists(select 1 from public.sacco_members where auth_user_id=(select auth.uid())));
create policy sacco_settings_admin_write on public.sacco_settings for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_minutes_read on public.sacco_minutes for select to authenticated using(exists(select 1 from public.sacco_members where auth_user_id=(select auth.uid())));
create policy sacco_minutes_admin_write on public.sacco_minutes for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_contributions_read on public.sacco_contributions for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_contributions_admin_write on public.sacco_contributions for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_loans_read on public.sacco_loans for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_loans_admin_write on public.sacco_loans for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_repayments_read on public.sacco_repayments for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_repayments_admin_write on public.sacco_repayments for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_membership_fees_read on public.sacco_membership_fees for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_membership_fees_admin_write on public.sacco_membership_fees for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_waivers_read on public.sacco_waivers for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_waivers_admin_write on public.sacco_waivers for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_requests_read on public.sacco_requests for select to authenticated using(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) or (select sacco_private.is_sacco_admin()));
create policy sacco_requests_admin_write on public.sacco_requests for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create policy sacco_requests_member_insert on public.sacco_requests for insert to authenticated with check(member_id in(select id from public.sacco_members where auth_user_id=(select auth.uid())) and status='PENDING' and amount>0 and legacy_key is null);
create policy sacco_financial_entries_read on public.sacco_financial_entries for select to authenticated using((select sacco_private.is_sacco_admin()));
create policy sacco_audit_entries_read on public.sacco_audit_entries for select to authenticated using((select sacco_private.is_sacco_admin()));
create policy sacco_import_runs_read on public.sacco_import_runs for select to authenticated using((select sacco_private.is_sacco_admin()));
create policy sacco_financial_entries_admin_write on public.sacco_financial_entries for all to authenticated using((select sacco_private.is_sacco_admin())) with check((select sacco_private.is_sacco_admin()));
create function sacco_private.record_change() returns trigger language plpgsql security definer set search_path='' as $$declare prev jsonb; next jsonb; rec_id text; begin prev:=case when tg_op<>'INSERT' then to_jsonb(old)-'screenshot_data'-'photo_data' else null end;next:=case when tg_op<>'DELETE' then to_jsonb(new)-'screenshot_data'-'photo_data' else null end;rec_id:=coalesce(next->>'id',prev->>'id','settings');insert into public.sacco_audit_entries(actor_user_id,event_kind,entity_table,entity_id,before_record,after_record) values((select auth.uid()),tg_op,tg_table_name,rec_id,prev,next);if tg_op='DELETE' then return old;else return new;end if;end$$;
revoke all on function sacco_private.record_change() from public,anon;
create trigger sacco_audit_changes after insert or update or delete on public.sacco_contributions for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_loans for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_repayments for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_financial_entries for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_membership_fees for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_waivers for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_requests for each row execute function sacco_private.record_change();
create trigger sacco_audit_changes after insert or update or delete on public.sacco_settings for each row execute function sacco_private.record_change();
commit;
